#include "tclInt.h"
#include <stdio.h>
#include <stdint.h>
typedef struct {Tcl_Size len; Tcl_Obj **elements; int isDouble; Tcl_Size refs;} Series;
static void snap(int c,const char*w,Tcl_Obj*o) {Series*r=o->typePtr&&strcmp(o->typePtr->name,"arithseries")==0?o->internalRep.twoPtrValue.ptr1:NULL;printf("S\t%d\t%s\t%s\t%d\t%ld\t%ld\t%d\t%d\n",c,w,o->typePtr?o->typePtr->name:"none",o->bytes!=NULL,(long)o->refCount,r?(long)r->len:-1,r?(int)r->refs:-1,r? r->elements!=NULL:0);}
int main(int argc,char**argv){Tcl_FindExecutable(argv[0]);Tcl_Interp*i=Tcl_CreateInterp();const char*s[]={"lseq 5","lseq 0","lseq -1","lseq 1 to 9 by 2","lseq 0 to 0.5 by 0.1","lseq 3 count 4 by 0","lseq 100000001","lseq 9223372036854775807 count 2","lseq 1 to 5 by -1"};for(int c=0;c<9;c++){int rc=Tcl_Eval(i,s[c]);Tcl_Obj*o=Tcl_GetObjResult(i);printf("R\t%d\t%d\n",c,rc);if(rc){printf("E\t%d\t%s\n",c,Tcl_GetString(o));continue;}Tcl_IncrRefCount(o);Tcl_ResetResult(i);snap(c,"original",o);Tcl_Size n;rc=Tcl_ListObjLength(i,o,&n);printf("L\t%d\t%d\t%ld\n",c,rc,(long)n);snap(c,"afterlength",o);Tcl_Obj*d=Tcl_DuplicateObj(o);Tcl_IncrRefCount(d);snap(c,"dup-original",o);snap(c,"duplicate",d);if(n){Tcl_Obj*a=NULL,*b=NULL;Tcl_ListObjIndex(i,d,0,&a);Tcl_ListObjIndex(i,d,0,&b);printf("I\t%d\t%s\t%d\t%ld\t%d\n",c,a->typePtr?a->typePtr->name:"none",a->bytes!=NULL,(long)a->refCount,a==b);printf("V\t%d\t%s\n",c,Tcl_GetString(a));Tcl_BounceRefCount(a);Tcl_BounceRefCount(b);snap(c,"afterindex",d);}Tcl_DecrRefCount(d);snap(c,"afterdrop",o);if(n<10){Tcl_Size count;Tcl_Obj**elems;Tcl_ListObjGetElements(i,o,&count,&elems);snap(c,"afterelements",o);if(count){Tcl_Obj*x=NULL;Tcl_ListObjIndex(i,o,0,&x);printf("C\t%d\t%ld\t%ld\t%d\n",c,(long)elems[0]->refCount,(long)x->refCount,x==elems[0]);Tcl_BounceRefCount(x);}printf("T\t%d\t%s\n",c,Tcl_GetString(o));snap(c,"afterstring",o);}Tcl_DecrRefCount(o);}Tcl_DeleteInterp(i);Tcl_Finalize();return 0;}
